#define PIXW (1.0 / iResolution.y)

void mainImage(out vec4 fragColor,in vec2 fragCoord){

    vec2 uv =  (fragCoord.xy - 0.5 *iResolution.xy) * PIXW;


    //将画布裁剪成好多个小画布
    uv *= 5.0;
    vec2 uvID = floor(uv);
    uv = fract(uv);
    uv -= 0.5;

    //令所有ID和为偶数的格子再次分裂
    if(int(uvID.x+uvID.y)%2 == 0){ 

        uv *=2.0;
        uv = fract(uv);
        uv -= 0.5;


    }


    uv = vec2(length(uv),atan(-uv.y,-uv.x));
    uv.y =uv.y/6.28+0.5;

    uv.y =  uv.y -iTime * 0.2;
    uv.y -= floor(uv.y);
    float ct = uv.y + iTime * 0.8;
    ct -= floor(ct);

    //fragColor = vec4(step(0.0,length(uv) - 0.5));
    //fragColor = vec4(step(length(uv) - 0.5,0.0));

    fragColor = vec4(smoothstep(0.0 + 10.0 * PIXW,0.0,uv.x-0.2*(sin(uv.y*10.*3.14)*.5+.8)));


    fragColor = mix(vec4(0.7,0.3,0.4,1.0)*fragColor,fragColor * vec4(0.1,0.3,0.2,1.0),ct);

}
